package com.example.expensetracker.service;import java.util.*;import org.springframework.stereotype.Service;import com.example.expensetracker.entity.Expense;import com.example.expensetracker.repository.ExpenseRepository;@Service public class ExpenseService{ExpenseRepository r; public ExpenseService(ExpenseRepository r){this.r=r;} public List<Expense> all(){return r.findAll();} public Expense save(Expense e){return r.save(e);}}